  -- ---- confirm popup: the retail card window with the performers' cards (util_cp_gw.lua in general_window) --------
  function UTIL_CP.GwClear()
    local G = UTIL_CP.GW
    pcall(funcLuaCommand, 3363400568, G.N)
    for i = 1, 4 do
      pcall(funcLuaCommand, 3363400568, G.H[i])
      pcall(funcLuaCommand, 3363400568, G.I[i])
    end
  end

  function UTIL_CP.Performers(player, list, picks, info)
    local function entry(h)
      for _, e in ipairs(list) do
        if h ~= 0 and e.hdl == h then
          return e
        end
      end
      if h ~= 0 then
        return UTIL_CP.Entry(h)
      end
      return {hdl = 0}
    end
    local out = {entry(player)}
    for _, c in ipairs(info.named) do
      local h = 0
      for _, e in ipairs(list) do
        if e.hdl ~= 0 and e.chara == c then
          h = e.hdl
        end
      end
      out[#out + 1] = entry(h)
    end
    for k = 1, info.free do
      out[#out + 1] = entry(picks[k] or 0)
    end
    return out
  end

  function UTIL_CP.Confirm(player, list, picks, info, mname)
    local s = UTIL_CP.Text(UTIL_CP.TX_ASK, mname)
    local perf = UTIL_CP.Performers(player, list, picks, info)
    local G = UTIL_CP.GW
    UTIL_CP.GwClear()
    local m = math.min(#perf, 4)
    local names = {}
    for i = 1, m do
      local e = perf[i]
      local el = (e.chara ~= nil and e.chara ~= 0 and type(e.element) == "number" and UTIL_CP.ELEM_SPR[e.element] ~= nil) and e.element or 0
      local ps = (type(e.pos) == "number" and e.pos >= 0 and e.pos <= 3) and e.pos + 1 or 0
      funcLuaCommand(3860611758, G.H[i], 0, e.hdl or 0, 1)
      funcLuaCommand(3860611758, G.I[i], 0, el * 10 + ps, 1)
      names[#names + 1] = string.format("%08X", UTIL_CP.U32(e.hdl or 0))
    end
    funcLuaCommand(3860611758, G.N, 0, m, 1)
    UTIL_CP.Log("confirm", m, "cards", table.concat(names, " "))
    funcLuaCommand(2289627655, s, G.WINDOW, 0, 0, 0, 0, false)
    funcLuaCommand(2351835063, 2, 0)
    coroutine.yield()
    local r = -1
    while r == nil or r < 0 do
      r = funcLuaCommand(1523741473)
      coroutine.yield()
    end
    while not funcLuaCommand(682363669) do
      coroutine.yield()
    end
    local okh, left = pcall(funcLuaCommand, 2947612279, G.N)
    if okh and left == true then
      UTIL_CP.Log("confirm: general_window did not take the cards (Utilities' util_cp_gw hook missing)")
    end
    UTIL_CP.GwClear()
    return r == 0
  end

  -- ---- the picker -------------------------------------------------------------------------------------------------
  -- one page: the pick for free slot `slot`; returns the list index (0-based) or nil (back)
  function UTIL_CP.Page(screen, list, picks, slot, info)
    for _, e in ipairs(list) do
      e.taken = false
      if e.hdl ~= 0 then
        for k = 1, info.free do
          if k ~= slot and picks[k] == e.hdl then
            e.taken = true
          end
        end
      end
    end
    local cur = picks[slot] or 0
    local sel = 0
    for i, e in ipairs(list) do
      if e.hdl == cur then
        sel = i - 1
      end
    end
    local first = math.max(0, math.min(sel, #list - UTIL_CP.VIEW))
    local title = string.format("%s %d / %d", UTIL_CP.Text(UTIL_CP.TX_SLOT), slot, info.free)
    UTIL_CP.ListShow(screen, true, list, first, sel, cur, title)
    UTIL_CP.Guide(screen, {{UTIL_CP.TX_ACCEPT, UTIL_CP.GL_ENTER, UTIL_CP.K_ENTER}, {UTIL_CP.TX_BACK, UTIL_CP.GL_BACK, UTIL_CP.K_BACK}})
    coroutine.yield()
    while true do
      coroutine.yield()
      if screen.Frame ~= nil then
        pcall(screen.Frame)
      end
      local moved = false
      if UTIL_CP.Key(UTIL_CP.K_BACK) then
        UTIL_CP.SE(UTIL_CP.SE_BACK)
        return nil
      elseif UTIL_CP.Key(UTIL_CP.K_ENTER) or UTIL_CP.Key(UTIL_CP.K_CLICK) then
        if list[sel + 1].taken then
          UTIL_CP.SE(UTIL_CP.SE_NG)
        else
          UTIL_CP.SE(UTIL_CP.SE_DECIDE)
          return sel
        end
      elseif UTIL_CP.Key(UTIL_CP.K_DOWN) and sel < #list - 1 then
        sel = sel + 1
        if sel >= first + UTIL_CP.VIEW then
          first = first + 1
        end
        moved = true
      elseif UTIL_CP.Key(UTIL_CP.K_UP) and sel > 0 then
        sel = sel - 1
        if sel < first then
          first = first - 1
        end
        moved = true
      end
      if moved then
        UTIL_CP.SE(UTIL_CP.SE_MOVE)
        UTIL_CP.ListShow(screen, true, list, first, sel, cur, title)
      end
    end
  end

  -- the picker for `skill` (info = UTIL_CP.ComboInfo(skill)) on `screen` (see the top of this part); a coroutine body
  function UTIL_CP.Open(screen, skill, info)
    local message = screen.Message or UTIL_CP.Message
    local mname = UTIL_CP.MoveName(skill)
    local player = screen.player
    if player == nil or player == 0 then
      UTIL_CP.SE(UTIL_CP.SE_NG)
      UTIL_CP.Log("open refused: no player known", string.format("skill %08X", skill))
      return
    end
    if info.free <= 0 then
      local names = {}
      for _, c in ipairs(info.named) do
        names[#names + 1] = UTIL_CP.CharaName(c)
      end
      UTIL_CP.SE(UTIL_CP.SE_NG)
      message(mname .. "\n" .. UTIL_CP.Text(UTIL_CP.TX_FIXED) .. ": " .. table.concat(names, ", "))
      return
    end
    local list = UTIL_CP.Candidates(screen, info)
    if list == nil then
      -- opened without a squad (story field, a scout): no one to choose from
      UTIL_CP.SE(UTIL_CP.SE_NG)
      message(UTIL_CP.Text(UTIL_CP.TX_NOTEAM))
      return
    end
    UTIL_CP.SE(UTIL_CP.SE_DECIDE)
    screen.Begin()
    UTIL_CP.picking = true
    local done, err = pcall(function()
      local saved = UTIL_CP.Get(player, skill)
      local picks = {}
      for k = 1, info.free do
        picks[k] = saved[k] or 0
      end
      UTIL_CP.Log("open", string.format("player %08X skill %08X performers %d free %d named %d team %d", player, skill,
        info.performers, info.free, #info.named, #list - 1))
      local slot = 1
      while slot >= 1 and slot <= info.free do
        local i = UTIL_CP.Page(screen, list, picks, slot, info)
        if i == nil then
          slot = slot - 1
        else
          picks[slot] = list[i + 1].hdl
          slot = slot + 1
        end
      end
      pcall(UTIL_CP.ListShow, screen, false, {}, 0, 0, 0)
      if slot > info.free then
        local same = true
        for k = 1, info.free do
          if (picks[k] or 0) ~= (saved[k] or 0) then
            same = false
          end
        end
        if same or UTIL_CP.Confirm(player, list, picks, info, mname) then
          local ok, r = pcall(funcLuaCommand, UTIL_CP.CMD_SET, player, skill, picks[1] or 0, picks[2] or 0, picks[3] or 0)
          UTIL_CP.SE((ok and r == true) and UTIL_CP.SE_OK or UTIL_CP.SE_NG)
          UTIL_CP.Log("saved", string.format("player %08X skill %08X -> %08X %08X %08X (%s)", player, skill,
            picks[1] or 0, picks[2] or 0, picks[3] or 0, tostring(r)))
        else
          UTIL_CP.Log("cancelled at confirm", string.format("skill %08X", skill))
        end
      else
        UTIL_CP.Log("cancelled", string.format("skill %08X", skill))
      end
    end)
    UTIL_CP.picking = false
    pcall(UTIL_CP.ListShow, screen, false, {}, 0, 0, 0)
    screen.Finish()
    if not done then
      UTIL_CP.Log("picker error", tostring(err))
    end
  end
  -- ===== end of the shared partner picker =====

  UTIL_CP.SKILL_TABLE_PRIO = {BG = 449, LIST = 450, ITEM = 451} -- the screen's own list popups (evt_ss_list) use these
  UTIL_CP.FOCUS_INDEX = 2603265800 -- (layer) -> focused instance
  UTIL_CP.FOCUS_SET = 1778826357 -- (layer, instance, true): the focus on that instance

  function UTIL_CP.SkillTableHost()
    local host = type(CharacterReforged) == "table" and CharacterReforged.SkillTable or nil
    if type(host) ~= "table" or type(host.L) ~= "table" then
      return nil
    end
    return host
  end

  -- the screen's squad: its team list t4[1..n15] (the registered squad), formation slots t5[i], formation n6
  function UTIL_CP.SkillTableMembers(locals)
    local team, count = locals.t4, locals.n15
    if type(team) ~= "table" or type(count) ~= "number" then
      return nil
    end
    local slots = locals.t5
    local out = {formation = locals.n6}
    for i = 1, count do
      local h = team[i]
      if type(h) == "number" and h ~= 0 then
        out[#out + 1] = {hdl = h, slot = type(slots) == "table" and slots[i] or nil, index = i}
      end
    end
    return out
  end

  -- the SCREEN table of util_cp_core for this screen (host = CharacterReforged.SkillTable, ctx of the press)
  function UTIL_CP.SkillTable(host, ctx)
    local locals = host.L
    local state = {row = ctx.row}
    local function cover(show)
      local screen_helpers = locals.PL
      if type(screen_helpers) == "table" and type(screen_helpers.ListCover) == "function" then
        pcall(screen_helpers.ListCover, show)
      end
    end
    local function refocus()
      local rows = locals.L_ROW
      if rows == nil or state.row == nil then
        return
      end
      local ok, at = pcall(funcLuaMenuCommand, UTIL_CP.FOCUS_INDEX, rows)
      if not ok or at ~= state.row then
        pcall(funcLuaMenuCommand, UTIL_CP.FOCUS_SET, rows, state.row, true)
      end
    end
    return {
      player = UTIL_CP.U32(ctx.chara),
      backdrop = false, -- the screen's list cover draws the blue backdrop
      Members = function()
        return UTIL_CP.SkillTableMembers(locals)
      end,
      Begin = function()
        cover(true)
      end,
      Frame = refocus,
      Finish = function()
        cover(false)
        refocus()
        if type(UpdateEquipItemInfo) == "function" then
          pcall(UpdateEquipItemInfo) -- the row's own guide and panel back
        end
      end,
      GuideMenu = function()
        return locals.n12
      end,
      Message = host.Message,
    }
  end

  Utilities = type(Utilities) == "table" and Utilities or {}

  -- the x_action entry of Character Reforged's skill table host (see the top of this file)
  function Utilities.SkillTablePartners(phase, ctx)
    local host = UTIL_CP.SkillTableHost()
    if host == nil or type(ctx) ~= "table" then
      return nil
    end
    if phase == "available" then
      if type(EVT_CPK) == "table" then
        return false -- Inazuma Fantasy's picker owns X on this screen
      end
      return type(ctx.row) == "number" and (ctx.move or 0) ~= 0 and UTIL_CP.ComboInfo(ctx.move) ~= nil
    elseif phase == "guide" then
      return true
    elseif phase ~= "press" then
      return nil
    end
    local skill = UTIL_CP.U32(ctx.move)
    local info = UTIL_CP.ComboInfo(skill)
    if info == nil then
      host.Sound("refused")
      return
    end
    UTIL_CP.Open(UTIL_CP.SkillTable(host, ctx), skill, info)
  end

  -- ---- the picker's layers and the focus while it runs (globals wrapped once per VM) -----------------------------
  function UTIL_CP.WrapSkillTableGlobal(name, make)
    UTIL_CP.skill_table_wrapped = UTIL_CP.skill_table_wrapped or {}
    if UTIL_CP.skill_table_wrapped[name] then
      return
    end
    local current = _ENV[name]
    if current == nil then
      return
    end
    _ENV[name] = make(current)
    UTIL_CP.skill_table_wrapped[name] = true
  end

  UTIL_CP.WrapSkillTableGlobal("OnSetupLayer", function(previous)
    return function(a1, a2, ...)
      if UTIL_CP.Ours(a1) then
        UTIL_CP.SetupLayer(a1, a2, UTIL_CP.SKILL_TABLE_PRIO)
        return
      end
      return previous(a1, a2, ...)
    end
  end)

  UTIL_CP.WrapSkillTableGlobal("OnOpenLayer", function(previous)
    return function(a1, a2, ...)
      if UTIL_CP.Ours(a1) then
        if not UTIL_CP.picking then
          pcall(funcLuaMenuCommand, 711242136, a1, a2, false)
        end
        return
      end
      return previous(a1, a2, ...)
    end
  end)

  -- a page is up: the D-pad / stick move the screen's focus too (its input stays on); the move is dropped here and
  -- the page's Frame puts the focus back on the move row
  UTIL_CP.WrapSkillTableGlobal("OnChangeFocus", function(previous)
    return function(a1, a2, ...)
      if UTIL_CP.picking then
        return
      end
      return previous(a1, a2, ...)
    end
  end)
end
